export const CUANGO_EXPLORACAO_RESUMO_RECORDS: FleetCycleRecord[] = RAW_EXPLORACAO_RESUMO.map(
  ([
    numero,
    equipamento,
    condutor,
    entrada,
    saida,
    inicio,
    fim,
    duracaoSeg,
    utilizacaoSeg,
    relantiSeg,
    paradoSeg,
    distanciaHoras,
    entradasCount,
    area,
  ]) => {
    const { nome, codigo } = splitDriverIdentity(condutor);
    return {
      id: `exp-resumo-15-11-2026-${numero}`,
      numero,
      equipamento,
      condutorCompleto: condutor,
      condutorNome: nome,
      condutorCodigo: codigo,
      entrada,
      saida,
      inicio,
      fim,
      data: '15/11/2026',
      horaEntrada: extractHourFromDateTime(entrada),
      entradasCount,
      duracaoSeg,
      distanciaHoras,
      utilizacaoSeg,
      relantiSeg,
      paradoSeg,
      produtivoSeg: Math.max(0, utilizacaoSeg - relantiSeg),
      contador: 'Indisponível',
      area,
      origemArquivo: ARQUIVO_EXPLORACAO_SEED,
      sourceSection: 'resumo',
    };
  }
);

